mapper.update:
UPDATE trainings
SET average_rating = (
    SELECT ROUND(AVG(r.rating), 1)
    FROM reviews r
    WHERE r.training_id = #{trainingId}
)
WHERE training_id = #{trainingId}

UPDATE trainer_profiles
SET total_average_rating = (
    SELECT ROUND(AVG(r.rating), 1)
    FROM reviews r
             JOIN trainings t ON r.training_id = t.training_id
    WHERE t.trainer_id = #{trainerId}
)
WHERE trainer_id = #{trainerId}
